package io.github.escosis.hwtfaceswap.lifecycle;


import io.github.escosis.hwtfaceswap.Tr;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * 无 Android/手表报文依赖的解除配对生命周期。运行时拥有它，界面模型关闭不取消系统请求。
 * 只接受已消费的应用确认令牌；系统返回 true、广播 extra、设置页关闭都不是解除配对证据。
 * 平台边界每次必须真实读取启用且有权限的适配器上、匹配 MAC 的当前 bond state。
 */
public final class DeviceRemovalController {
    public enum Bond { NONE, BONDED, BONDING, ADAPTER_OFF, PERMISSION_REQUIRED, UNKNOWN }
    public enum Request { ACCEPTED, REJECTED, UNSUPPORTED, ADAPTER_OFF, PERMISSION_REQUIRED, UNKNOWN }
    public interface Platform {
        Bond readBond(String address);
        Request requestRemoval(String address);
        /** 事件只触发重新读取，不提供成功证据；null 表示适配器状态变化。 */
        void observe(Event listener);
        boolean openSettings();
    }
    public interface Event { void changed(String address); }
    public interface Queue { void post(Runnable task); void delay(Runnable task,long millis); long now(); }
    public interface Transport {
        boolean busy();
        /** 在同一协议串行队列内完成；不得断开不同 MAC。 */
        void stopTarget(String address);
    }
    public static final class Record {
        public final String address;public final long token,generation;public final boolean attempted,cleanupStarted;
        public Record(String address,long token,long generation,boolean attempted,boolean cleanupStarted) {
            this.address=address;this.token=token;this.generation=generation;this.attempted=attempted;this.cleanupStarted=cleanupStarted;
        }
    }
    public interface Records {
        List<Record> pending()throws Exception;
        Record begin(String address,long token)throws Exception;
        Record markAttempted(String address,long token)throws Exception;
        Record markCleanupStarted(String address,long token)throws Exception;
        void clearCredentials(String address)throws Exception;
        void removeHistory(String address)throws Exception;
        void finish(String address,long token)throws Exception;
        void abandon(String address,long token)throws Exception;
    }
    public static final class Snapshot {
        public final boolean pending,working,needsSettings,success;
        public final String address,message;public final long token,revision;
        private Snapshot(boolean pending,boolean working,boolean settings,boolean success,String address,String message,long token,long revision) {
            this.pending=pending;this.working=working;needsSettings=settings;this.success=success;
            this.address=address;this.message=message;this.token=token;this.revision=revision;
        }
    }
    public interface Listener { void changed(Snapshot snapshot); }
    private static final long TIMEOUT_MS=20000L, POLL_MS=500L;
    private final Platform platform;private final Queue queue;private final Transport transport;private final Records records;
    private final CopyOnWriteArrayList<Listener> listeners=new CopyOnWriteArrayList<>();
    private volatile Snapshot state=new Snapshot(false,false,false,false,null,"",0,0);
    // 以下字段仅在串行队列使用；reservation/state 的消费以 synchronized 保证一次性。
    private volatile Record record;private boolean markerStarted;private long watchSerial;private Request requestResult;

    public DeviceRemovalController(Platform platform,Queue queue,Transport transport,Records records) {
        this.platform=Objects.requireNonNull(platform);this.queue=Objects.requireNonNull(queue);
        this.transport=Objects.requireNonNull(transport);this.records=Objects.requireNonNull(records);
        restore();
    }
    public Snapshot snapshot(){return state;}
    public boolean blocksAddress(String address) {
        Snapshot s=state;return s.pending&&s.address!=null&&s.address.equalsIgnoreCase(address==null?"":address);
    }
    public void addListener(Listener listener){listeners.addIfAbsent(listener);listener.changed(state);}
    public void removeListener(Listener listener){listeners.remove(listener);}
    private synchronized void publish(boolean pending,boolean working,boolean settings,boolean success,String address,String message,long token) {
        Snapshot next=new Snapshot(pending,working,settings,success,address,message,token,state.revision+1);
        state=next;for(Listener listener:listeners)listener.changed(next);
    }
    private void restore() {
        try {
            List<Record> saved=records.pending();if(saved.isEmpty())return;
            record=saved.get(0);markerStarted=true;
            publish(true,true,false,false,record.address,Tr.tr("正在重新核实待处理设备的系统配对状态", "Nuova verifica dello stato di abbinamento di sistema del dispositivo in sospeso", "Re-checking the system pairing state of the pending device", "Volviendo a comprobar el estado de emparejamiento del dispositivo pendiente", "Nouvelle vérification de l'état d'association système de l'appareil en attente", "A verificar de novo o estado de emparelhamento do dispositivo pendente", "Verificando de novo o status de pareamento do dispositivo pendente", "Повторна проверка на системното сдвояване на чакащото устройство", "Bekleyen cihazın sistem eşleştirme durumu yeniden kontrol ediliyor", "Kopplungsstatus des ausstehenden Geräts wird erneut geprüft", "Повторная проверка системного сопряжения ожидающего устройства"),record.token);
            String address=record.address;long token=record.token;
            queue.post(()->start(address,token,false));
        } catch(Exception e) {
            publish(true,false,false,false,null,Tr.tr("无法读取待处理解除配对标记；未执行系统请求或资料清理，请重新打开应用后重试", "Impossibile leggere il contrassegno di annullamento abbinamento in sospeso; nessuna richiesta di sistema o pulizia dei dati eseguita. Riapri l'app e riprova", "Couldn't read the pending unpair flag; no system request or data cleanup performed. Reopen the app and try again", "No se pudo leer la marca de desemparejamiento pendiente; no se hizo ninguna solicitud al sistema ni limpieza de datos. Vuelve a abrir la app e inténtalo", "Impossible de lire l'indicateur de dissociation en attente ; aucune demande système ni nettoyage effectués. Rouvrez l'app et réessayez", "Não foi possível ler a marca de desemparelhamento pendente; nenhum pedido ao sistema nem limpeza de dados feitos. Volte a abrir a app e tente de novo", "Não foi possível ler a marca de despareamento pendente; nenhuma solicitação ao sistema nem limpeza de dados feitas. Abra o app de novo e tente outra vez", "Не може да се прочете отметката за чакащо разкачване; не е направена системна заявка или изчистване на данни. Отворете приложението отново и опитайте пак", "Bekleyen eşleştirme kaldırma işareti okunamadı; sistem isteği veya veri temizliği yapılmadı. Uygulamayı yeniden açıp tekrar deneyin", "Die Markierung für die ausstehende Entkopplung konnte nicht gelesen werden; keine Systemanfrage und keine Datenbereinigung ausgeführt. Öffne die App erneut und versuche es noch einmal", "Не удалось прочитать отметку ожидающего снятия сопряжения; системный запрос и очистка данных не выполнены. Откройте приложение заново и повторите"),0);
        }
    }
    /** 返回 false 表示未接受新的任务。确认本身由应用 UI 的一次 token 消费完成。 */
    public synchronized boolean request(String address,long token) {
        String mac=canonical(address);
        if(mac==null||state.pending||transport.busy())return false;
        publish(true,true,false,false,mac,Tr.tr("正在保存待处理标记并停止该设备的本应用连接", "Salvataggio del contrassegno in sospeso e arresto della connessione dell'app a questo dispositivo", "Saving the pending flag and stopping the app's connection to this device", "Guardando la marca pendiente y deteniendo la conexión de la app con este dispositivo", "Enregistrement de l'indicateur en attente et arrêt de la connexion de l'app à cet appareil", "A guardar a marca pendente e a parar a ligação da app a este dispositivo", "Salvando a marca pendente e interrompendo a conexão do app com este dispositivo", "Запазване на чакащата отметка и спиране на връзката на приложението с това устройство", "Bekleyen işaret kaydediliyor ve uygulamanın bu cihazla bağlantısı durduruluyor", "Ausstehende Markierung wird gespeichert und die Verbindung der App zu diesem Gerät gestoppt", "Сохранение ожидающей отметки и остановка подключения приложения к этому устройству"),token);
        queue.post(()->start(mac,token,true));return true;
    }
    public void retry(){Snapshot s=state;if(s.pending&&s.address!=null)queue.post(()->start(s.address,s.token,true));}
    /** 界面探测：只有尚未开始资料清理时才允许撤回，避免把已部分清理的设备放回可用状态。 */
    public boolean cancelable(){Record current=record;return state.pending&&current!=null&&!current.cleanupStarted;}
    /** 撤回待处理解除配对：一次都没有清除凭据/历史，因此设备可以直接恢复使用。 */
    public void cancel(){
        Snapshot s=state;if(!s.pending||s.address==null)return;
        queue.post(()->{
            if(!owned(s.address,s.token))return;
            Record current=record;
            if(current==null||current.cleanupStarted){pending(s.address,s.token,false,Tr.tr("清理已经开始，无法撤回解除配对；请完成系统解除配对后重新检查", "La pulizia è già iniziata, impossibile annullare l'annullamento abbinamento; completa l'annullamento abbinamento di sistema e ricontrolla", "Cleanup has already started, unpairing can't be undone; complete the system unpairing and check again", "La limpieza ya empezó, no se puede deshacer el desemparejamiento; termina el desemparejamiento del sistema y vuelve a comprobar", "Le nettoyage a déjà commencé, impossible d'annuler la dissociation ; terminez la dissociation système et vérifiez à nouveau", "A limpeza já começou, não é possível anular o desemparelhamento; conclua o desemparelhamento do sistema e verifique de novo", "A limpeza já começou, não é possível desfazer o despareamento; conclua o despareamento do sistema e verifique de novo", "Изчистването вече е започнало, разкачването не може да се отмени; завършете системното разкачване и проверете пак", "Temizlik zaten başladı, eşleştirme kaldırma geri alınamaz; sistem eşleştirme kaldırmasını tamamlayıp tekrar kontrol edin", "Die Bereinigung hat bereits begonnen, die Entkopplung kann nicht rückgängig gemacht werden; schließe die Systementkopplung ab und prüfe erneut", "Очистка уже началась, снятие сопряжения отменить нельзя; завершите системное снятие сопряжения и проверьте снова"));return;}
            try{records.abandon(s.address,s.token);}
            catch(Exception e){pending(s.address,s.token,false,Tr.tr("撤回解除配对失败，请重试（", "Impossibile ripristinare l'abbinamento, riprova (", "Couldn't undo unpairing, try again (", "No se pudo deshacer el desemparejamiento, inténtalo de nuevo (", "Impossible d'annuler la dissociation, réessayez (", "Não foi possível anular o desemparelhamento, tente de novo (", "Não foi possível desfazer o despareamento, tente de novo (", "Разкачването не може да се отмени, опитайте пак (", "Eşleştirme kaldırma geri alınamadı, tekrar deneyin (", "Entkopplung konnte nicht rückgängig gemacht werden, versuche es erneut (", "Не удалось отменить снятие сопряжения, повторите (")+code(e)+"）");return;}
            record=null;markerStarted=false;requestResult=null;++watchSerial;
            publish(false,false,false,false,s.address,Tr.tr("已取消解除配对；系统配对与本应用资料均保持原状，可以重新连接", "Annullamento abbinamento revocato; l'abbinamento di sistema e i dati dell'app sono invariati, puoi riconnetterti", "Unpairing undone; the system pairing and the app data are unchanged, you can reconnect", "Desemparejamiento deshecho; el emparejamiento del sistema y los datos de la app no cambian, puedes volver a conectar", "Dissociation annulée ; l'association système et les données de l'app sont inchangées, vous pouvez vous reconnecter", "Desemparelhamento anulado; o emparelhamento do sistema e os dados da app não mudaram, pode voltar a ligar", "Despareamento desfeito; o pareamento do sistema e os dados do app não mudaram, você pode conectar de novo", "Разкачването е отменено; системното сдвояване и данните на приложението са непроменени, можете да се свържете отново", "Eşleştirme kaldırma geri alındı; sistem eşleştirmesi ve uygulama verileri değişmedi, yeniden bağlanabilirsiniz", "Entkopplung rückgängig gemacht; Systemkopplung und App-Daten sind unverändert, du kannst dich wieder verbinden", "Снятие сопряжения отменено; системное сопряжение и данные приложения не изменились, можно подключиться снова"),s.token);
        });
    }
    /** 设置页返回/活动恢复只核实，不再次提交隐藏方法。 */
    public void verify(){Snapshot s=state;if(s.pending&&s.address!=null)queue.post(()->start(s.address,s.token,false));}
    public void openSettings() {
        Snapshot s=state;if(!s.pending||s.address==null)return;
        queue.post(()->{
            if(!owned(s.address,s.token))return;
            if(!platform.openSettings())pending(s.address,s.token,true,Tr.tr("无法打开系统蓝牙设置；请手动进入系统设置解除此 MAC 的配对，再点击重新检查", "Impossibile aprire le impostazioni Bluetooth; vai manualmente nelle impostazioni di sistema, annulla l'abbinamento di questo MAC e tocca Ricontrolla", "Couldn't open Bluetooth settings; go to system settings manually, unpair this MAC and tap Check again", "No se pudieron abrir los ajustes Bluetooth; ve a los ajustes del sistema, desempareja esta MAC y toca Volver a comprobar", "Impossible d'ouvrir les paramètres Bluetooth ; allez dans les paramètres système, dissociez cette adresse MAC et touchez Vérifier à nouveau", "Não foi possível abrir as definições Bluetooth; vá às definições do sistema, desemparelhe este MAC e toque em Verificar de novo", "Não foi possível abrir as configurações Bluetooth; vá às configurações do sistema, desfaça o pareamento deste MAC e toque em Verificar de novo", "Настройките на Bluetooth не могат да се отворят; отидете в системните настройки, разкачете този MAC и докоснете „Проверка пак“", "Bluetooth ayarları açılamadı; sistem ayarlarına gidin, bu MAC'in eşleştirmesini kaldırın ve Tekrar kontrol et'e dokunun", "Bluetooth-Einstellungen konnten nicht geöffnet werden; geh in die Systemeinstellungen, entkopple diese MAC und tippe auf Erneut prüfen", "Не удалось открыть настройки Bluetooth; перейдите в настройки системы, снимите сопряжение с этим MAC и нажмите «Проверить снова»"));
        });
    }
    private boolean owned(String address,long token){Snapshot s=state;return s.pending&&s.token==token&&address.equals(s.address);}
    private void start(String address,long token,boolean mayAttempt) {
        if(!owned(address,token))return;
        ++watchSerial;
        if(transport.busy()) {
            if(!markerStarted)publish(false,false,false,false,address,Tr.tr("当前表盘操作尚未结束，未提交解除配对请求", "L'operazione sul quadrante in corso non è ancora terminata; richiesta di annullamento abbinamento non inviata", "The current watch face operation hasn't finished yet; unpair request not sent", "La operación de esfera en curso aún no ha terminado; solicitud de desemparejamiento no enviada", "L'opération en cours sur le cadran n'est pas encore terminée ; demande de dissociation non envoyée", "A operação em curso no mostrador ainda não terminou; pedido de desemparelhamento não enviado", "A operação em andamento no mostrador ainda não terminou; solicitação de despareamento não enviada", "Текущата операция с циферблат още не е приключила; заявката за разкачване не е изпратена", "Süren kadran işlemi henüz bitmedi; eşleştirme kaldırma isteği gönderilmedi", "Der laufende Zifferblatt-Vorgang ist noch nicht beendet; Entkopplungsanfrage nicht gesendet", "Текущая операция с циферблатом ещё не завершена; запрос на снятие сопряжения не отправлен"),token);
            else pending(address,token,false,Tr.tr("请先结束当前表盘操作；待处理解除配对资料保持不变", "Termina prima l'operazione sul quadrante in corso; i dati dell'annullamento abbinamento in sospeso restano invariati", "Finish the current watch face operation first; the pending unpair data remains unchanged", "Termina primero la operación de esfera en curso; los datos de desemparejamiento pendientes no cambian", "Terminez d'abord l'opération en cours sur le cadran ; les données de dissociation en attente restent inchangées", "Termine primeiro a operação em curso no mostrador; os dados de desemparelhamento pendentes não mudam", "Conclua primeiro a operação em andamento no mostrador; os dados de despareamento pendentes não mudam", "Първо завършете текущата операция с циферблат; данните за чакащото разкачване остават непроменени", "Önce süren kadran işlemini bitirin; bekleyen eşleştirme kaldırma verileri değişmeden kalır", "Beende zuerst den laufenden Zifferblatt-Vorgang; die Daten der ausstehenden Entkopplung bleiben unverändert", "Сначала завершите текущую операцию с циферблатом; данные ожидающего снятия сопряжения не изменились"));
            return;
        }
        publish(true,true,false,false,address,Tr.tr("正在核实该设备的系统配对状态", "Verifica dello stato di abbinamento di sistema di questo dispositivo", "Checking the system pairing state of this device", "Comprobando el estado de emparejamiento del sistema de este dispositivo", "Vérification de l'état d'association système de cet appareil", "A verificar o estado de emparelhamento do sistema deste dispositivo", "Verificando o status de pareamento do sistema deste dispositivo", "Проверка на системното сдвояване на това устройство", "Bu cihazın sistem eşleştirme durumu kontrol ediliyor", "Kopplungsstatus dieses Geräts im System wird geprüft", "Проверка системного сопряжения этого устройства"),token);
        try {
            markerStarted=true; // commit(false) 也可能已改变 Journal 内存；不能把 record==null 当作“没有标记”。
            record=records.begin(address,token); // 返回之前须真实 commit 成功；失败不允许调用系统方法。
            transport.stopTarget(address);      // 同队列屏障，之后的旧帧/配对回调必须失效。
        } catch(Exception e) {
            pending(address,token,false,Tr.tr("待处理标记或连接停止未可靠完成；未继续提交系统请求，请重试（", "Contrassegno in sospeso o arresto della connessione non completati in modo affidabile; richiesta di sistema non inviata, riprova (", "Pending flag or connection stop not reliably completed; system request not sent, try again (", "Marca pendiente o parada de la conexión no completadas de forma fiable; solicitud al sistema no enviada, inténtalo de nuevo (", "Indicateur en attente ou arrêt de la connexion non terminés de façon fiable ; demande système non envoyée, réessayez (", "Marca pendente ou paragem da ligação não concluídas de forma fiável; pedido ao sistema não enviado, tente de novo (", "Marca pendente ou interrupção da conexão não concluídas de forma confiável; solicitação ao sistema não enviada, tente de novo (", "Чакащата отметка или спирането на връзката не са завършени надеждно; системната заявка не е изпратена, опитайте пак (", "Bekleyen işaret veya bağlantının durdurulması güvenilir şekilde tamamlanmadı; sistem isteği gönderilmedi, tekrar deneyin (", "Ausstehende Markierung oder Verbindungsstopp nicht zuverlässig abgeschlossen; Systemanfrage nicht gesendet, versuche es erneut (", "Ожидающая отметка или остановка подключения не завершены надёжно; системный запрос не отправлен, повторите (")+code(e)+"）");return;
        }
        try { platform.observe(this::event); }
        catch(RuntimeException e) { /* 监听不可用时仍可真实读取/手动重试，不能假设成功。 */ }
        Bond bond=read(address);
        if(bond==Bond.NONE){cleanup(address,token);return;}
        if(unavailable(address,token,bond))return;
        if(!mayAttempt||record.attempted) {
            pending(address,token,true,record.cleanupStarted?
                Tr.tr("上次清理尚未可靠完成，系统当前仍显示配对；请核实此 MAC 的系统配对后重试", "La pulizia precedente non è stata completata in modo affidabile e il sistema mostra ancora l'abbinamento; verifica l'abbinamento di sistema di questo MAC e riprova", "The previous cleanup didn't complete reliably and the system still shows the pairing; check the system pairing of this MAC and try again", "La limpieza anterior no terminó de forma fiable y el sistema sigue mostrando el emparejamiento; comprueba el emparejamiento de esta MAC e inténtalo de nuevo", "Le nettoyage précédent ne s'est pas terminé de façon fiable et le système affiche toujours l'association ; vérifiez l'association système de cette adresse MAC et réessayez", "A limpeza anterior não terminou de forma fiável e o sistema ainda mostra o emparelhamento; verifique o emparelhamento do sistema deste MAC e tente de novo", "A limpeza anterior não terminou de forma confiável e o sistema ainda mostra o pareamento; verifique o pareamento do sistema deste MAC e tente de novo", "Предишното изчистване не приключи надеждно и системата още показва сдвояване; проверете системното сдвояване на този MAC и опитайте пак", "Önceki temizlik güvenilir şekilde tamamlanmadı ve sistem hâlâ eşleştirmeyi gösteriyor; bu MAC'in sistem eşleştirmesini kontrol edip tekrar deneyin", "Die vorherige Bereinigung wurde nicht zuverlässig abgeschlossen und das System zeigt weiterhin die Kopplung; prüfe die Systemkopplung dieser MAC und versuche es erneut", "Предыдущая очистка не завершилась надёжно, и система всё ещё показывает сопряжение; проверьте системное сопряжение этого MAC и повторите"):
                Tr.tr("系统仍显示此 MAC 已配对或正在配对；请在系统蓝牙设置解除配对，再点击重新检查", "Il sistema mostra ancora questo MAC come abbinato o in abbinamento; annulla l'abbinamento nelle impostazioni Bluetooth di sistema e tocca Ricontrolla", "The system still shows this MAC as paired or pairing; unpair it in system Bluetooth settings and tap Check again", "El sistema sigue mostrando esta MAC como emparejada o emparejándose; desempareja en los ajustes Bluetooth del sistema y toca Volver a comprobar", "Le système affiche toujours cette adresse MAC comme associée ou en cours d'association ; dissociez-la dans les paramètres Bluetooth du système et touchez Vérifier à nouveau", "O sistema ainda mostra este MAC como emparelhado ou a emparelhar; desemparelhe nas definições Bluetooth do sistema e toque em Verificar de novo", "O sistema ainda mostra este MAC como pareado ou pareando; desfaça o pareamento nas configurações Bluetooth do sistema e toque em Verificar de novo", "Системата още показва този MAC като сдвоен или в процес на сдвояване; разкачете го от системните настройки на Bluetooth и докоснете „Проверка пак“", "Sistem bu MAC'i hâlâ eşleştirilmiş veya eşleştiriliyor olarak gösteriyor; sistem Bluetooth ayarlarından eşleştirmeyi kaldırıp Tekrar kontrol et'e dokunun", "Das System zeigt diese MAC weiterhin als gekoppelt oder in Kopplung; entkopple sie in den Bluetooth-Einstellungen des Systems und tippe auf Erneut prüfen", "Система всё ещё показывает этот MAC как сопряжённый или в процессе сопряжения; снимите сопряжение в настройках Bluetooth системы и нажмите «Проверить снова»"));
            return;
        }
        try {
            // 在调用之前持久记录“已尝试”。崩溃窗口可能少执行一次，但绝不会自动重发一次。
            record=records.markAttempted(address,token);
        } catch(Exception e) {
            pending(address,token,true,Tr.tr("系统请求尚未提交，尝试标记无法可靠保存；请在系统蓝牙设置处理后重新检查（", "Richiesta di sistema non inviata: impossibile salvare in modo affidabile il contrassegno; intervieni nelle impostazioni Bluetooth di sistema e ricontrolla (", "System request not sent: the flag couldn't be saved reliably; handle it in system Bluetooth settings and check again (", "Solicitud al sistema no enviada: no se pudo guardar la marca de forma fiable; resuélvelo en los ajustes Bluetooth del sistema y vuelve a comprobar (", "Demande système non envoyée : l'indicateur n'a pas pu être enregistré de façon fiable ; réglez-le dans les paramètres Bluetooth du système et vérifiez à nouveau (", "Pedido ao sistema não enviado: não foi possível guardar a marca de forma fiável; resolva nas definições Bluetooth do sistema e verifique de novo (", "Solicitação ao sistema não enviada: não foi possível salvar a marca de forma confiável; resolva nas configurações Bluetooth do sistema e verifique de novo (", "Системната заявка не е изпратена: отметката не може да се запази надеждно; уредете го от системните настройки на Bluetooth и проверете пак (", "Sistem isteği gönderilmedi: işaret güvenilir şekilde kaydedilemedi; sistem Bluetooth ayarlarından halledip tekrar kontrol edin (", "Systemanfrage nicht gesendet: die Markierung konnte nicht zuverlässig gespeichert werden; kläre es in den Bluetooth-Einstellungen des Systems und prüfe erneut (", "Системный запрос не отправлен: отметку не удалось надёжно сохранить; решите это в настройках Bluetooth системы и проверьте снова (")+code(e)+"）");return;
        }
        try { requestResult=platform.requestRemoval(address); }
        catch(RuntimeException e){requestResult=Request.UNKNOWN;}
        // 无论返回值如何都重新读真实状态；只有 NONE 才允许本应用资料清理。
        bond=read(address);
        if(bond==Bond.NONE){cleanup(address,token);return;}
        if(unavailable(address,token,bond))return;
        if(requestResult==Request.ACCEPTED) {
            pending(address,token,false,Tr.tr("已向系统提交解除配对请求，尚未证实成功；正在等待真实配对状态", "Richiesta di annullamento abbinamento inviata al sistema, esito non ancora confermato; in attesa dello stato di abbinamento reale", "Unpair request sent to the system, result not confirmed yet; waiting for the real pairing state", "Solicitud de desemparejamiento enviada al sistema, resultado aún sin confirmar; esperando el estado real de emparejamiento", "Demande de dissociation envoyée au système, résultat pas encore confirmé ; en attente de l'état réel d'association", "Pedido de desemparelhamento enviado ao sistema, resultado ainda não confirmado; a aguardar o estado real de emparelhamento", "Solicitação de despareamento enviada ao sistema, resultado ainda não confirmado; aguardando o status real de pareamento", "Заявката за разкачване е изпратена до системата, резултатът още не е потвърден; изчакване на реалното състояние на сдвояването", "Eşleştirme kaldırma isteği sisteme gönderildi, sonuç henüz doğrulanmadı; gerçek eşleştirme durumu bekleniyor", "Entkopplungsanfrage an das System gesendet, Ergebnis noch nicht bestätigt; warten auf den echten Kopplungsstatus", "Запрос на снятие сопряжения отправлен системе, результат ещё не подтверждён; ожидание реального состояния сопряжения"));
            long serial=++watchSerial,started=queue.now();
            queue.delay(()->poll(address,token,serial,started),POLL_MS);
        } else {
            String detail=requestResult==Request.UNSUPPORTED?Tr.tr("系统不允许本应用直接解除配对", "Il sistema non consente all'app di annullare direttamente l'abbinamento", "The system doesn't allow the app to unpair directly", "El sistema no permite a la app desemparejar directamente", "Le système ne permet pas à l'app de dissocier directement", "O sistema não permite que a app desemparelhe diretamente", "O sistema não permite que o app desfaça o pareamento diretamente", "Системата не позволява на приложението да разкачва директно", "Sistem, uygulamanın eşleştirmeyi doğrudan kaldırmasına izin vermiyor", "Das System erlaubt der App kein direktes Entkoppeln", "Система не позволяет приложению напрямую снимать сопряжение"):
                requestResult==Request.REJECTED?Tr.tr("系统拒绝直接解除配对请求", "Il sistema ha rifiutato la richiesta di annullamento abbinamento diretto", "The system rejected the direct unpair request", "El sistema rechazó la solicitud de desemparejamiento directo", "Le système a refusé la demande de dissociation directe", "O sistema recusou o pedido de desemparelhamento direto", "O sistema recusou a solicitação de despareamento direto", "Системата отказа заявката за директно разкачване", "Sistem doğrudan eşleştirme kaldırma isteğini reddetti", "Das System hat die direkte Entkopplungsanfrage abgelehnt", "Система отклонила прямой запрос на снятие сопряжения"):Tr.tr("无法确定系统是否接受解除配对请求", "Impossibile stabilire se il sistema ha accettato la richiesta di annullamento abbinamento", "Couldn't tell whether the system accepted the unpair request", "No se pudo saber si el sistema aceptó la solicitud de desemparejamiento", "Impossible de savoir si le système a accepté la demande de dissociation", "Não foi possível saber se o sistema aceitou o pedido de desemparelhamento", "Não foi possível saber se o sistema aceitou a solicitação de despareamento", "Не може да се установи дали системата е приела заявката за разкачване", "Sistemin eşleştirme kaldırma isteğini kabul edip etmediği anlaşılamadı", "Unklar, ob das System die Entkopplungsanfrage angenommen hat", "Не удалось понять, приняла ли система запрос на снятие сопряжения");
            pending(address,token,true,detail+Tr.tr("；资料尚未清除。请在系统蓝牙设置解除此 MAC 的配对后重新检查", "; dati non ancora cancellati. Annulla l'abbinamento di questo MAC nelle impostazioni Bluetooth di sistema e ricontrolla", "; data not cleared yet. Unpair this MAC in system Bluetooth settings and check again", "; datos aún no borrados. Desempareja esta MAC en los ajustes Bluetooth del sistema y vuelve a comprobar", " ; données pas encore effacées. Dissociez cette adresse MAC dans les paramètres Bluetooth du système et vérifiez à nouveau", "; dados ainda não apagados. Desemparelhe este MAC nas definições Bluetooth do sistema e verifique de novo", "; dados ainda não apagados. Desfaça o pareamento deste MAC nas configurações Bluetooth do sistema e verifique de novo", "; данните още не са изтрити. Разкачете този MAC от системните настройки на Bluetooth и проверете пак", "; veriler henüz silinmedi. Bu MAC'in eşleştirmesini sistem Bluetooth ayarlarından kaldırıp tekrar kontrol edin", "; Daten noch nicht gelöscht. Entkopple diese MAC in den Bluetooth-Einstellungen des Systems und prüfe erneut", "; данные ещё не удалены. Снимите сопряжение с этим MAC в настройках Bluetooth системы и проверьте снова"));
        }
    }
    private void event(String address) {
        Snapshot s=state;
        if(!s.pending||s.address==null||(address!=null&&!s.address.equalsIgnoreCase(address)))return;
        queue.post(()->{
            if(!owned(s.address,s.token))return;
            Bond bond=read(s.address);
            if(bond==Bond.NONE)cleanup(s.address,s.token);
            else unavailable(s.address,s.token,bond);
        });
    }
    private void poll(String address,long token,long serial,long started) {
        if(!owned(address,token)||watchSerial!=serial)return;
        Bond bond=read(address);
        if(bond==Bond.NONE){cleanup(address,token);return;}
        if(unavailable(address,token,bond)){++watchSerial;return;}
        if(queue.now()-started>=TIMEOUT_MS) {
            ++watchSerial;pending(address,token,true,Tr.tr("等待系统解除配对超时，当前仍未证实 BOND_NONE；资料尚未清除，请在系统蓝牙设置处理后重新检查", "Timeout in attesa dell'annullamento abbinamento di sistema, BOND_NONE non ancora confermato; dati non ancora cancellati. Intervieni nelle impostazioni Bluetooth di sistema e ricontrolla", "Timed out waiting for system unpairing, BOND_NONE not confirmed yet; data not cleared yet. Handle it in system Bluetooth settings and check again", "Tiempo agotado esperando el desemparejamiento del sistema, BOND_NONE aún sin confirmar; datos aún no borrados. Resuélvelo en los ajustes Bluetooth del sistema y vuelve a comprobar", "Délai dépassé en attendant la dissociation système, BOND_NONE pas encore confirmé ; données pas encore effacées. Réglez-le dans les paramètres Bluetooth du système et vérifiez à nouveau", "Tempo esgotado à espera do desemparelhamento do sistema, BOND_NONE ainda não confirmado; dados ainda não apagados. Resolva nas definições Bluetooth do sistema e verifique de novo", "Tempo esgotado aguardando o despareamento do sistema, BOND_NONE ainda não confirmado; dados ainda não apagados. Resolva nas configurações Bluetooth do sistema e verifique de novo", "Времето за изчакване на системното разкачване изтече, BOND_NONE още не е потвърдено; данните още не са изтрити. Уредете го от системните настройки на Bluetooth и проверете пак", "Sistemin eşleştirmeyi kaldırması beklenirken zaman aşımı, BOND_NONE henüz doğrulanmadı; veriler henüz silinmedi. Sistem Bluetooth ayarlarından halledip tekrar kontrol edin", "Zeitüberschreitung beim Warten auf die Systementkopplung, BOND_NONE noch nicht bestätigt; Daten noch nicht gelöscht. Kläre es in den Bluetooth-Einstellungen des Systems und prüfe erneut", "Время ожидания системного снятия сопряжения истекло, BOND_NONE ещё не подтверждён; данные ещё не удалены. Решите это в настройках Bluetooth системы и проверьте снова"));return;
        }
        queue.delay(()->poll(address,token,serial,started),POLL_MS);
    }
    private Bond read(String address) {try {Bond value=platform.readBond(address);return value==null?Bond.UNKNOWN:value;}catch(RuntimeException e){return Bond.UNKNOWN;}}
    private boolean unavailable(String address,long token,Bond bond) {
        if(bond==Bond.ADAPTER_OFF)pending(address,token,true,Tr.tr("系统蓝牙未开启，无法确认解除配对；资料尚未清除，请开启蓝牙后重新检查", "Bluetooth di sistema non attivo: impossibile confermare l'annullamento abbinamento; dati non ancora cancellati. Attiva il Bluetooth e ricontrolla", "System Bluetooth is off: can't confirm unpairing; data not cleared yet. Turn on Bluetooth and check again", "Bluetooth del sistema desactivado: no se puede confirmar el desemparejamiento; datos aún no borrados. Activa el Bluetooth y vuelve a comprobar", "Bluetooth système désactivé : impossible de confirmer la dissociation ; données pas encore effacées. Activez le Bluetooth et vérifiez à nouveau", "Bluetooth do sistema desligado: não é possível confirmar o desemparelhamento; dados ainda não apagados. Ligue o Bluetooth e verifique de novo", "Bluetooth do sistema desligado: não é possível confirmar o despareamento; dados ainda não apagados. Ligue o Bluetooth e verifique de novo", "Системният Bluetooth е изключен: разкачването не може да се потвърди; данните още не са изтрити. Включете Bluetooth и проверете пак", "Sistem Bluetooth'u kapalı: eşleştirme kaldırma doğrulanamıyor; veriler henüz silinmedi. Bluetooth'u açıp tekrar kontrol edin", "System-Bluetooth ist aus: Entkopplung kann nicht bestätigt werden; Daten noch nicht gelöscht. Schalte Bluetooth ein und prüfe erneut", "Системный Bluetooth выключен: подтвердить снятие сопряжения нельзя; данные ещё не удалены. Включите Bluetooth и проверьте снова"));
        else if(bond==Bond.PERMISSION_REQUIRED)pending(address,token,true,Tr.tr("附近设备连接权限不可用，无法确认解除配对；资料尚未清除，请在系统应用权限中为腕镜授予附近设备权限后重新检查", "Autorizzazione Dispositivi nelle vicinanze non disponibile: impossibile confermare l'annullamento abbinamento; dati non ancora cancellati. Concedi a WristMirror l'autorizzazione Dispositivi nelle vicinanze nelle impostazioni dell'app e ricontrolla", "Nearby devices permission unavailable: can't confirm unpairing; data not cleared yet. Grant WristMirror the Nearby devices permission in the app settings and check again", "Permiso de Dispositivos cercanos no disponible: no se puede confirmar el desemparejamiento; datos aún no borrados. Concede a WristMirror el permiso de Dispositivos cercanos en los ajustes de la app y vuelve a comprobar", "Autorisation Appareils à proximité indisponible : impossible de confirmer la dissociation ; données pas encore effacées. Accordez à WristMirror l'autorisation Appareils à proximité dans les paramètres de l'app et vérifiez à nouveau", "Permissão Dispositivos próximos indisponível: não é possível confirmar o desemparelhamento; dados ainda não apagados. Conceda ao WristMirror a permissão Dispositivos próximos nas definições da app e verifique de novo", "Permissão Dispositivos por perto indisponível: não é possível confirmar o despareamento; dados ainda não apagados. Conceda ao WristMirror a permissão Dispositivos por perto nas configurações do app e verifique de novo", "Разрешението „Устройства наблизо“ не е налично: разкачването не може да се потвърди; данните още не са изтрити. Дайте на WristMirror разрешението „Устройства наблизо“ в настройките на приложението и проверете пак", "Yakındaki cihazlar izni yok: eşleştirme kaldırma doğrulanamıyor; veriler henüz silinmedi. Uygulama ayarlarından WristMirror'a Yakındaki cihazlar iznini verip tekrar kontrol edin", "Berechtigung „Geräte in der Nähe“ nicht verfügbar: Entkopplung kann nicht bestätigt werden; Daten noch nicht gelöscht. Erteile WristMirror die Berechtigung „Geräte in der Nähe“ in den App-Einstellungen und prüfe erneut", "Разрешение «Устройства поблизости» недоступно: подтвердить снятие сопряжения нельзя; данные ещё не удалены. Выдайте WristMirror разрешение «Устройства поблизости» в настройках приложения и проверьте снова"));
        else if(bond==Bond.UNKNOWN)pending(address,token,true,Tr.tr("无法可靠读取此 MAC 的当前系统配对状态；资料尚未清除，请核实系统蓝牙设置后重新检查", "Impossibile leggere in modo affidabile questo MAC nello stato di abbinamento di sistema; dati non ancora cancellati. Verifica le impostazioni Bluetooth di sistema e ricontrolla", "Couldn't reliably read this MAC's current system pairing state; data not cleared yet. Check system Bluetooth settings and check again", "No se pudo leer de forma fiable esta MAC en el estado de emparejamiento del sistema; datos aún no borrados. Revisa los ajustes Bluetooth del sistema y vuelve a comprobar", "Impossible de lire de façon fiable cette adresse MAC dans l'état d'association système ; données pas encore effacées. Vérifiez les paramètres Bluetooth du système et vérifiez à nouveau", "Não foi possível ler de forma fiável este MAC no estado de emparelhamento do sistema; dados ainda não apagados. Verifique as definições Bluetooth do sistema e verifique de novo", "Não foi possível ler de forma confiável este MAC no status de pareamento do sistema; dados ainda não apagados. Verifique as configurações Bluetooth do sistema e verifique de novo", "Този MAC не може да се прочете надеждно в системното състояние на сдвояване; данните още не са изтрити. Проверете системните настройки на Bluetooth и проверете пак", "Bu MAC güvenilir şekilde okunamadı (sistem eşleştirme durumu); veriler henüz silinmedi. Sistem Bluetooth ayarlarını kontrol edip tekrar deneyin", "Diese MAC konnte nicht zuverlässig gelesen werden (Kopplungsstatus im System); Daten noch nicht gelöscht. Prüfe die Bluetooth-Einstellungen des Systems und prüfe erneut", "Не удалось надёжно прочитать этот MAC в системном состоянии сопряжения; данные ещё не удалены. Проверьте настройки Bluetooth системы и проверьте снова"));
        else return false;
        return true;
    }
    private void cleanup(String address,long token) {
        if(!owned(address,token))return;
        ++watchSerial;publish(true,true,false,false,address,Tr.tr("系统读到未配对，正在持久清理此 MAC 的本应用资料", "Il sistema risulta non abbinato: pulizia definitiva dei dati dell'app per questo MAC in corso", "The system reports not paired: permanently clearing the app data for this MAC", "El sistema indica que no está emparejado: borrando definitivamente los datos de la app para esta MAC", "Le système indique non associé : effacement définitif des données de l'app pour cette adresse MAC", "O sistema indica que não está emparelhado: a apagar definitivamente os dados da app para este MAC", "O sistema indica que não está pareado: apagando definitivamente os dados do app para este MAC", "Системата отчита, че не е сдвоено: окончателно изтриване на данните на приложението за този MAC", "Sistem eşleştirilmemiş diyor: bu MAC için uygulama verileri kalıcı olarak siliniyor", "Das System meldet nicht gekoppelt: App-Daten für diese MAC werden endgültig gelöscht", "Система сообщает, что сопряжения нет: окончательное удаление данных приложения для этого MAC"),token);
        try {
            record=records.markCleanupStarted(address,token);
            // 提交清理标记期间适配器或权限也可能变化，紧邻清理再读一次真实状态。
            Bond bond=read(address);
            if(bond!=Bond.NONE) {
                if(!unavailable(address,token,bond))pending(address,token,true,Tr.tr("系统配对状态已变化，未继续清理；请核实此 MAC 后重试", "Lo stato di abbinamento di sistema è cambiato, pulizia interrotta; verifica questo MAC e riprova", "The system pairing state changed, cleanup stopped; check this MAC and try again", "El estado de emparejamiento del sistema cambió, limpieza detenida; comprueba esta MAC e inténtalo de nuevo", "L'état d'association système a changé, nettoyage arrêté ; vérifiez cette adresse MAC et réessayez", "O estado de emparelhamento do sistema mudou, limpeza parada; verifique este MAC e tente de novo", "O status de pareamento do sistema mudou, limpeza interrompida; verifique este MAC e tente de novo", "Системното състояние на сдвояването се промени, изчистването е спряно; проверете този MAC и опитайте пак", "Sistem eşleştirme durumu değişti, temizlik durduruldu; bu MAC'i kontrol edip tekrar deneyin", "Der Kopplungsstatus im System hat sich geändert, Bereinigung gestoppt; prüfe diese MAC und versuche es erneut", "Системное состояние сопряжения изменилось, очистка остановлена; проверьте этот MAC и повторите"));
                return;
            }
            transport.stopTarget(address);
            records.clearCredentials(address);
            records.removeHistory(address);
            records.finish(address,token);
            record=null;markerStarted=false;requestResult=null;
            publish(false,false,false,true,address,Tr.tr("系统已确认解除配对；此设备在腕镜的账号、认证、本机身份和连接记录已清除", "Il sistema ha confermato l'annullamento abbinamento; account, autenticazione, identità locale e cronologia connessioni di questo dispositivo in WristMirror sono stati cancellati", "The system confirmed unpairing; this device's account, authentication, local identity and connection history in WristMirror have been cleared", "El sistema confirmó el desemparejamiento; la cuenta, la autenticación, la identidad local y el historial de conexiones de este dispositivo en WristMirror se han borrado", "Le système a confirmé la dissociation ; le compte, l'authentification, l'identité locale et l'historique des connexions de cet appareil dans WristMirror ont été effacés", "O sistema confirmou o desemparelhamento; a conta, a autenticação, a identidade local e o histórico de ligações deste dispositivo no WristMirror foram apagados", "O sistema confirmou o despareamento; a conta, a autenticação, a identidade local e o histórico de conexões deste dispositivo no WristMirror foram apagados", "Системата потвърди разкачването; профилът, удостоверяването, локалната самоличност и историята на връзките на това устройство в WristMirror са изтрити", "Sistem eşleştirmenin kaldırıldığını doğruladı; bu cihazın WristMirror'daki hesabı, kimlik doğrulaması, yerel kimliği ve bağlantı geçmişi silindi", "Das System hat die Entkopplung bestätigt; Konto, Authentifizierung, lokale Identität und Verbindungsverlauf dieses Geräts in WristMirror wurden gelöscht", "Система подтвердила снятие сопряжения; аккаунт, аутентификация, локальная идентичность и история подключений этого устройства в WristMirror удалены"),token);
        } catch(Exception e) {
            pending(address,token,false,Tr.tr("系统曾读到未配对，但本应用清理尚未可靠保存，可能已部分清理；此 MAC 仍被阻断，请重新检查并重试（", "Il sistema aveva rilevato il mancato abbinamento, ma la pulizia dei dati dell'app non salvata in modo affidabile potrebbe essere parziale; questo MAC resta bloccato, ricontrolla e riprova (", "The system had reported not paired, but app data cleanup not reliably saved and may be partial; this MAC stays blocked, check again and retry (", "El sistema había indicado que no estaba emparejado, pero la limpieza de datos de la app no guardada de forma fiable puede ser parcial; esta MAC sigue bloqueada, vuelve a comprobar y reintenta (", "Le système avait indiqué non associé, mais le nettoyage des données de l'app non enregistré de façon fiable peut être partiel ; cette adresse MAC reste bloquée, vérifiez à nouveau et réessayez (", "O sistema tinha indicado que não estava emparelhado, mas a limpeza dos dados da app não guardada de forma fiável pode estar incompleta; este MAC continua bloqueado, verifique de novo e tente outra vez (", "O sistema tinha indicado que não estava pareado, mas a limpeza dos dados do app não salva de forma confiável pode estar incompleta; este MAC continua bloqueado, verifique de novo e tente outra vez (", "Системата беше отчела, че не е сдвоено, но изчистването на данните на приложението не е запазено надеждно и може да е частично; този MAC остава блокиран, проверете пак и опитайте отново (", "Sistem daha önce eşleştirilmemiş demişti, ancak uygulama verilerinin temizliği güvenilir şekilde kaydedilmedi ve kısmi olabilir; bu MAC engelli kalıyor, tekrar kontrol edip yeniden deneyin (", "Das System hatte nicht gekoppelt gemeldet, aber die Bereinigung der App-Daten nicht zuverlässig gespeichert und eventuell unvollständig; diese MAC bleibt gesperrt, prüfe erneut und versuche es noch einmal (", "Система ранее сообщила, что сопряжения нет, но очистка данных приложения не сохранена надёжно и может быть частичной; этот MAC остаётся заблокированным, проверьте снова и повторите (")+code(e)+"）");
        }
    }
    private void pending(String address,long token,boolean settings,String message){if(owned(address,token))publish(true,false,settings,false,address,message,token);}
    private static String code(Exception e){String value=e.getMessage();return value!=null&&value.matches("[A-Z0-9_]{1,80}")?value:e.getClass().getSimpleName();}
    private static String canonical(String address){return address!=null&&address.matches("(?i)[0-9a-f]{2}(?::[0-9a-f]{2}){5}")?address.toUpperCase(Locale.ROOT):null;}
}
